INSERT INTO jobs (id, title, category, sector, icon, summary, qualification) VALUES
  ('junior-data-analyst', 'Junior Data Analyst', 'Technology', 'Technology & Data', 'chart', 'Turn raw data into reports that help teams make day-to-day decisions.', 'A relevant diploma, degree or demonstrated equivalent skills. Employers set their own criteria.'),
  ('business-intelligence-analyst', 'Business Intelligence Analyst', 'Technology', 'Technology & Data', 'chart', 'Translate business questions into metrics, dashboards and regular performance reports.', 'Relevant analytics or business studies and a portfolio of reporting work are typical examples.'),
  ('frontend-web-developer', 'Frontend Web Developer', 'Technology', 'Web & Software', 'code', 'Build responsive interfaces and make websites usable across devices.', 'A relevant qualification or a demonstrable web portfolio is a typical starting point.'),
  ('it-support-technician', 'IT Support Technician', 'Technology', 'IT Services', 'monitor', 'Help people solve device and connectivity issues and document recurring problems.', 'A relevant certificate or diploma and practical troubleshooting examples can support an application.'),
  ('digital-marketing-executive', 'Digital Marketing Executive', 'Creative', 'Marketing & Media', 'spark', 'Plan content and track how digital campaigns perform.', 'A communications or business qualification, or sample campaigns showing practical skills.'),
  ('operations-coordinator', 'Operations Coordinator', 'Business', 'Business Operations', 'briefcase', 'Keep daily work organised through scheduling, tracking and reporting.', 'Business or administrative studies and examples of organised project work can be relevant.'),
  ('automotive-technician', 'Automotive Technician', 'Engineering', 'Automotive & TVET', 'wrench', 'Inspect vehicles, support routine servicing and document diagnostic work.', 'Employers may require a relevant SKM or equivalent training. Check qualification and supervision requirements for the work.'),
  ('industrial-maintenance-technician', 'Industrial Maintenance Technician', 'Engineering', 'Manufacturing & TVET', 'wrench', 'Support preventive maintenance and document equipment issues in a manufacturing setting.', 'A relevant SKM or technical diploma may be expected. Confirm the training and authorisation needed for practical work.')
