  ('business-intelligence-analyst', 0, 'Build an operations dashboard from a fictional sales dataset.'),
  ('business-intelligence-analyst', 1, 'Document how each metric is calculated and checked.'),
  ('frontend-web-developer', 0, 'Build a responsive portfolio with an accessible form.'),
  ('frontend-web-developer', 1, 'Test it with a keyboard and on a narrow screen, then record your fixes.'),
  ('it-support-technician', 0, 'Create a troubleshooting knowledge base for three common support tickets.'),
  ('it-support-technician', 1, 'Include reproducible checks, outcomes and escalation notes.'),
  ('digital-marketing-executive', 0, 'Draft a two-week sample campaign for a fictional local business.'),
  ('digital-marketing-executive', 1, 'Analyse the example campaign results and explain what you would change.'),
  ('operations-coordinator', 0, 'Build a stock or service tracker for a fictional small business.'),
  ('operations-coordinator', 1, 'Summarise late handoffs and propose a change to the process.'),
  ('automotive-technician', 0, 'With a qualified supervisor, observe a routine diagnostic exercise and record the symptoms and checks.'),
  ('automotive-technician', 1, 'Prepare a service checklist for supervisor review, including hazards and when to stop and escalate.'),
