-- Generated by `npm run supabase:seed:generate` from src/db/seed-data.js.

-- Apply after app-schema.sql. Safe to re-run for the built-in reference/demo data.

BEGIN;

ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, description = EXCLUDED.description;

ON CONFLICT (id) DO UPDATE SET label = EXCLUDED.label;

ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, category = EXCLUDED.category, sector = EXCLUDED.sector, icon = EXCLUDED.icon, summary = EXCLUDED.summary, qualification = EXCLUDED.qualification;

ON CONFLICT (job_id, skill_id) DO UPDATE SET level = EXCLUDED.level, weight = EXCLUDED.weight;

ON CONFLICT (job_id, interest_id) DO NOTHING;

ON CONFLICT (job_id, position) DO UPDATE SET text = EXCLUDED.text;

ON CONFLICT (job_id, position) DO UPDATE SET title = EXCLUDED.title;

ON CONFLICT (job_id, position) DO UPDATE SET brief = EXCLUDED.brief;

DELETE FROM profile_skills
WHERE user_id IN (SELECT id FROM users WHERE kind = 'demo_template');
DELETE FROM profile_interests
WHERE user_id IN (SELECT id FROM users WHERE kind = 'demo_template');

ON CONFLICT (id) DO UPDATE SET kind = EXCLUDED.kind, persona_key = EXCLUDED.persona_key;

ON CONFLICT (user_id) DO UPDATE SET name = EXCLUDED.name, headline = EXCLUDED.headline, mbti = EXCLUDED.mbti, holland_codes_json = EXCLUDED.holland_codes_json, qualification = EXCLUDED.qualification, field_of_study = EXCLUDED.field_of_study, location = EXCLUDED.location, experience = EXCLUDED.experience, projects = EXCLUDED.projects, budget = EXCLUDED.budget, weekly_hours = EXCLUDED.weekly_hours, learning_mode = EXCLUDED.learning_mode;

ON CONFLICT (user_id) DO UPDATE SET started = EXCLUDED.started, target_job_id = EXCLUDED.target_job_id;

ON CONFLICT (user_id, skill_id) DO UPDATE SET evidence_level = EXCLUDED.evidence_level;

ON CONFLICT (user_id, interest_id) DO NOTHING;

COMMIT;
